function sumOfUnique(nums) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let alone = true;
    for (let j = 0; j < nums.length; j++) if (j !== i && nums[j] === nums[i]) alone = false;
    if (alone) total += nums[i];
  }
  return total;
}

