function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 10);
  // A narrow value range makes repeats common; a wide one leaves many values unique.
  const top = size === 'large' ? (rand() < 0.5 ? 100 : 60) : (rand() < 0.6 ? 6 : 100);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
